"""Migration: take the seeder's own filename out of five patients' clinical notes.

WHAT WAS WRONG
--------------
Five consultations carry this string in `remarks`:

    "Mock consultation entry generated by populate_records.py"

`remarks` is the column the Patient Profile screen prints under the heading
"Additional Notes" (templates/patient_profile.html, `consultation.remarks_display`),
so a Health Center Staff member opening PAT-003, PAT-009, PAT-012, PAT-013 or
PAT-014 reads a Python filename where a clinician's note belongs.

This is the same defect the commit "Stop showing the operator our filenames"
closed, and it is here for the reason that commit could not reach it: that work
fixed the CODE that showed filenames. These are rows. A string sitting in the
database is not touched by changing the template that renders it.

WHY NULL, AND NOT A REPLACEMENT SENTENCE
----------------------------------------
The obvious fix is to write something neutral in its place -- "No additional
notes recorded", or similar. That would be wrong twice over.

First, it would be a new claim. Nobody wrote a note on these visits; a sentence
saying a clinician considered the question and had nothing to add is not the same
thing as no note, and a medical record must not blur the two. The one outcome
worse than a visit with no notes is a visit with notes nobody wrote.

Second, the application already has an answer for this exact state and is already
using it. `remarks` is nullable, NINE of the twenty-seven consultations already
hold NULL, and models/consultations.py `_to_consultation()` gives every clinical
field a `<field>_display` twin that renders NULL as MISSING_TEXT -- "Not
recorded". So the screen already says the true thing, in the project's own
wording, for rows in this state. Writing a sentence of our own would put a
second, hand-made phrasing beside the one the renderer produces, and the two
would drift.

NULL therefore is not "blanking the field". It is putting these five rows into
the state the other nine are already in, and letting the renderer speak.

WHAT THIS TOUCHES
-----------------
`consultations.remarks`, on the five rows whose remarks match the seeded string
EXACTLY, and nothing else. Every other column of those five rows, every other row
in the table, and every other table is verified unchanged. The whole thing is one
transaction: if verification fails, nothing is committed.

populate_records.py has been corrected alongside this script to seed NULL, so a
database rebuilt from scratch comes out right. This script exists for the
database that is already here, which a reseed would not touch -- the seeder skips
consultations that already exist.

Idempotent -- re-running is a no-op. A row already holding NULL is counted as
already done; a row holding some OTHER text is a note a real person wrote and is
reported and left alone rather than overwritten.

Run:  python migrate_clear_seeded_remarks.py
"""
import sqlite3
import sys

import config

SEEDED_REMARK = "Mock consultation entry generated by populate_records.py"

# Spelled out per row rather than discovered by a LIKE, so the scope of this
# migration is reviewable here and in the commit without running anything. The
# patient label is carried only to make the output and the review readable; the
# UPDATE is keyed on the consultation id.
TARGETS = {
    1: "PAT-013 Mina Pascual, visit of 2026-08-07",
    2: "PAT-014 Nathan Quinones, visit of 2026-08-06",
    3: "PAT-003 Carla Dela Rosa, visit of 2026-08-05",
    4: "PAT-009 Isabel Lopez, visit of 2026-08-04",
    5: "PAT-012 Lorenzo Ocampo, visit of 2026-08-03",
}


def snapshot(conn):
    return {row["id"]: dict(row) for row in conn.execute(
        "SELECT * FROM consultations ORDER BY id")}


def main():
    conn = sqlite3.connect(config.DATABASE)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")

    before = snapshot(conn)
    print(f"consultations before migration: {len(before)}")

    applied, already, mismatched, missing = [], [], [], []

    for consultation_id, label in TARGETS.items():
        row = before.get(consultation_id)
        if row is None:
            missing.append(consultation_id)
            continue
        current = row["remarks"]
        if current is None:
            already.append(consultation_id)
            continue
        if current != SEEDED_REMARK:
            mismatched.append((consultation_id, label, current))
            continue
        conn.execute(
            "UPDATE consultations SET remarks = NULL WHERE id = ?", (consultation_id,)
        )
        applied.append((consultation_id, label, current))

    print(f"records corrected:  {len(applied)}")
    for consultation_id, label, was in applied:
        print(f"  consultation #{consultation_id} -- {label}")
        print(f"      {was!r}")
        print(f"   -> NULL  (screen prints \"Not recorded\")")
    if already:
        print(f"already NULL:       {len(already)} "
              f"({', '.join('#' + str(i) for i in already)})")
    if mismatched:
        print(f"left alone:         {len(mismatched)}")
        for consultation_id, label, current in mismatched:
            print(f"  #{consultation_id} {label}: holds {current!r} -- "
                  "a real note, not the seeded string; not touched")
    if missing:
        print(f"not in database:    {', '.join('#' + str(i) for i in missing)}")

    after = snapshot(conn)
    problems = []

    if len(before) != len(after):
        problems.append(f"row count changed: {len(before)} -> {len(after)}")

    untouched = 0
    for consultation_id, old in before.items():
        new = after.get(consultation_id)
        if new is None:
            problems.append(f"consultation #{consultation_id} disappeared")
            continue
        changed = [c for c, v in old.items() if new[c] != v]
        if not changed:
            untouched += 1
            continue
        if consultation_id not in TARGETS:
            problems.append(
                f"#{consultation_id} was not in scope but changed: {changed}")
            continue
        for column in changed:
            if column != "remarks":
                problems.append(
                    f"#{consultation_id}.{column}: {old[column]!r} -> {new[column]!r} "
                    "(outside this migration's remit)"
                )

    # The point of the exercise: no clinical note anywhere may still name a
    # source file. This catches a sixth row the audit did not find as well as an
    # incomplete run of this script.
    for consultation_id, row in after.items():
        for column in ("chief_complaint", "diagnosis", "treatment_plan", "remarks"):
            value = row[column] or ""
            if "populate_records" in value or ".py" in value:
                problems.append(
                    f"#{consultation_id}.{column} still names a source file: {value!r}")

    if problems:
        conn.rollback()
        conn.close()
        print("\nMIGRATION PROBLEMS -- nothing was committed:")
        for problem in problems:
            print("  -", problem)
        sys.exit(1)

    conn.commit()

    print(f"\nconsultations after migration:  {len(after)}")
    print(f"rows untouched:                 {untouched}")
    null_remarks = sum(1 for row in after.values() if row["remarks"] is None)
    print(f"consultations with no note:     {null_remarks} "
          "(all render \"Not recorded\")")
    print("No clinical field in any consultation names a source file.")

    conn.close()


if __name__ == "__main__":
    main()
